// Performance Optimization Report - Charts
// Generated by Trae Work
(function() {
  var style = getComputedStyle(document.documentElement);
  var accent = style.getPropertyValue('--accent').trim() || '#4B3FE3';
  var accent2 = style.getPropertyValue('--accent2').trim() || '#6F6FFF';
  var green = style.getPropertyValue('--green').trim() || '#4CAF50';
  var orange = style.getPropertyValue('--orange').trim() || '#FF9800';
  var red = style.getPropertyValue('--red').trim() || '#E91E63';
  var muted = style.getPropertyValue('--muted').trim() || '#6b6b80';
  var ink = style.getPropertyValue('--ink').trim() || '#1a1a2e';
  var rule = style.getPropertyValue('--rule').trim() || '#E0DEFF';

  // Chart 1: Performance Score Progression
  var chartScore = document.getElementById('chart-score');
  if (chartScore && typeof echarts !== 'undefined') {
    var chart1 = echarts.init(chartScore);
    chart1.setOption({
      title: {
        text: 'Performance 得分逐步提升',
        left: 'center',
        textStyle: { fontSize: 14, fontWeight: 600, color: ink }
      },
      tooltip: {
        trigger: 'axis',
        formatter: function(params) {
          var p = params[0];
          return p.name + '<br/>得分: <b>' + p.value + '</b>/100';
        }
      },
      grid: { left: '8%', right: '8%', bottom: '15%', top: '18%' },
      xAxis: {
        type: 'category',
        data: ['基线', '步骤1-2\n内联脚本+重排', '步骤3\nDOMPurify defer', '步骤4-5\nCSS preload+懒加载', '步骤6\nGzip压缩'],
        axisLabel: { fontSize: 11, color: muted, interval: 0, rotate: 0 },
        axisLine: { lineStyle: { color: rule } }
      },
      yAxis: {
        type: 'value',
        min: 0,
        max: 100,
        axisLabel: { fontSize: 11, color: muted },
        splitLine: { lineStyle: { color: rule, type: 'dashed' } },
        axisLine: { show: false }
      },
      series: [{
        type: 'bar',
        data: [
          { value: 59, itemStyle: { color: red } },
          { value: 70, itemStyle: { color: orange } },
          { value: 75, itemStyle: { color: accent2 } },
          { value: 82, itemStyle: { color: accent } },
          { value: 90, itemStyle: { color: green } }
        ],
        barWidth: '45%',
        label: {
          show: true,
          position: 'top',
          fontSize: 13,
          fontWeight: 700,
          color: ink,
          formatter: '{c}'
        },
        markLine: {
          silent: true,
          symbol: 'none',
          lineStyle: { color: red, type: 'dashed', width: 2 },
          data: [{
            yAxis: 85,
            label: {
              formatter: '阈值 85',
              color: red,
              fontSize: 11,
              position: 'insideEndTop'
            }
          }]
        }
      }]
    });
    window.addEventListener('resize', function() { chart1.resize(); });
  }

  // Chart 2: Key Metrics Trend
  var chartMetrics = document.getElementById('chart-metrics');
  if (chartMetrics && typeof echarts !== 'undefined') {
    var chart2 = echarts.init(chartMetrics);
    chart2.setOption({
      title: {
        text: '关键性能指标变化趋势（秒）',
        left: 'center',
        textStyle: { fontSize: 14, fontWeight: 600, color: ink }
      },
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'cross' }
      },
      legend: {
        data: ['LCP', 'FCP', 'Speed Index'],
        bottom: 0,
        textStyle: { fontSize: 12, color: muted },
        itemWidth: 16,
        itemHeight: 10
      },
      grid: { left: '10%', right: '8%', bottom: '15%', top: '18%' },
      xAxis: {
        type: 'category',
        data: ['基线', '步骤1-2', '步骤3', '步骤4-5', '步骤6'],
        axisLabel: { fontSize: 11, color: muted },
        axisLine: { lineStyle: { color: rule } }
      },
      yAxis: {
        type: 'value',
        name: '秒',
        nameTextStyle: { color: muted, fontSize: 11 },
        axisLabel: { fontSize: 11, color: muted },
        splitLine: { lineStyle: { color: rule, type: 'dashed' } },
        axisLine: { show: false }
      },
      series: [
        {
          name: 'LCP',
          type: 'line',
          data: [3.5, 2.8, 2.5, 2.2, 1.9],
          smooth: true,
          symbol: 'circle',
          symbolSize: 8,
          lineStyle: { color: red, width: 3 },
          itemStyle: { color: red },
          label: {
            show: true,
            position: 'top',
            fontSize: 11,
            fontWeight: 600,
            color: red,
            formatter: '{c}s'
          }
        },
        {
          name: 'FCP',
          type: 'line',
          data: [2.0, 1.5, 1.2, 1.1, 1.0],
          smooth: true,
          symbol: 'circle',
          symbolSize: 8,
          lineStyle: { color: orange, width: 2 },
          itemStyle: { color: orange }
        },
        {
          name: 'Speed Index',
          type: 'line',
          data: [2.0, 1.6, 1.3, 1.1, 1.0],
          smooth: true,
          symbol: 'circle',
          symbolSize: 8,
          lineStyle: { color: accent, width: 2 },
          itemStyle: { color: accent }
        }
      ]
    });
    window.addEventListener('resize', function() { chart2.resize(); });
  }
})();
